const OptimizedImagesAudit = require('../../../audits/byte-efficiency/uses-optimized-images.js');

function generateArtifacts(images) {
  const optimizedImages = [];
  const imageElements = [];

  for (const image of images) {
    const mimeType = image.mimeType || 'image/png';
    const url = `http://example.com/${image.name}`;

    optimizedImages.push({
      url,
      mimeType,
      ...image,
    });

    imageElements.push({
      src: url,
      naturalWidth: image.width,
      naturalHeight: image.height,
    });
  }

  return {
    URL: {finalUrl: 'http://example.com/'},
    ImageElements: imageElements,
    OptimizedImages: optimizedImages,
  };
}

const artifacts = generateArtifacts([
  {name: 'spritesheet2.png', originalSize: 54000, width: 1000, height: 1000},
]);

const auditResult = OptimizedImagesAudit.audit_(artifacts);

console.log(auditResult);
